A trie (prefix tree) stores words character by character along a path, so words with the same prefix share nodes. Insert, search and prefix lookups take O(length of word).

```python
class Trie:
    def __init__(self):
        self.root = {}

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True            # end-of-word marker

    def _find(self, s):
        node = self.root
        for ch in s:
            if ch not in node:
                return None
            node = node[ch]
        return node

    def search(self, word):
        node = self._find(word)
        return bool(node and "$" in node)

    def starts_with(self, prefix):
        return self._find(prefix) is not None

t = Trie()
t.insert("car")
print(t.search("car"), t.search("ca"), t.starts_with("ca"))  # True False True
```

Bellman-Ford finds shortest paths from one source in a weighted graph, even with negative edge weights. It relaxes every edge `V - 1` times; one more pass that still improves a distance proves a negative cycle is reachable.

```python
def bellman_ford(n, edges, start):
    dist = [float("inf")] * n
    dist[start] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            raise ValueError("negative cycle")
    return dist

edges = [(0, 1, 4), (0, 2, 5), (2, 1, -3), (1, 3, 2)]
print(bellman_ford(4, edges, 0))  # [0, 2, 5, 4]
```

It runs in O(V * E). Use Dijkstra when all weights are non-negative; it is faster.

